#!/usr/bin/env python3
"""Emit one buffered dpkg or RPM installed-package snapshot as NDJSON."""
import datetime
import hashlib
import json
import os
import shutil
import subprocess
import sys
import time
import uuid

SCHEMA = 1
CONTROL = {"\x00", "\n", "\r", "\t"}


def utc(epoch):
    return datetime.datetime.fromtimestamp(epoch, datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def run(argv):
    environment = {"PATH": "/usr/sbin:/usr/bin:/sbin:/bin", "LC_ALL": "C", "LANG": "C"}
    result = subprocess.run(argv, stdin=subprocess.DEVNULL, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, encoding="utf-8", errors="strict", timeout=120, env=environment, check=False)
    if result.returncode != 0:
        raise RuntimeError(f"command_failed:{os.path.basename(argv[0])}:{result.returncode}")
    return result.stdout


def checked(value, field):
    if not value or any(character in value for character in CONTROL):
        raise ValueError(f"invalid_{field}")
    return value


def package_id(manager, name, architecture):
    canonical = json.dumps([manager, name, architecture], ensure_ascii=True, separators=(",", ":"))
    return hashlib.sha256(canonical.encode("ascii")).hexdigest()


def dpkg_rows(command):
    output = run([command, "-W", "-f=${binary:Package}\t${Architecture}\t${Version}\t${db:Status-Status}\\n"])
    rows = []
    for number, line in enumerate(output.splitlines(), 1):
        fields = line.split("\t")
        if len(fields) != 4:
            raise ValueError(f"dpkg_field_count:{number}")
        name, architecture, version, status = fields
        if status != "installed":
            continue
        name = checked(name, "package_name")
        architecture = checked(architecture, "package_arch")
        version = checked(version, "version_identity")
        rows.append({"package_manager": "dpkg", "package_name": name, "package_arch": architecture, "version_identity": version, "package_status": status, "package_id": package_id("dpkg", name, architecture)})
    return rows


def rpm_rows(command):
    output = run([command, "-qa", "--queryformat", "%{NAME}\t%{ARCH}\t%{EPOCH}\t%{VERSION}\t%{RELEASE}\\n"])
    rows = []
    for number, line in enumerate(output.splitlines(), 1):
        fields = line.split("\t")
        if len(fields) != 5:
            raise ValueError(f"rpm_field_count:{number}")
        name, architecture, epoch, version, release = fields
        name = checked(name, "package_name")
        architecture = checked(architecture, "package_arch")
        epoch = "0" if epoch in {"", "(none)"} else checked(epoch, "package_epoch")
        version = checked(version, "package_version")
        release = checked(release, "package_release")
        identity = checked(f"{epoch}:{version}-{release}", "version_identity")
        rows.append({"package_manager": "rpm", "package_name": name, "package_arch": architecture, "package_epoch": epoch, "package_version": version, "package_release": release, "version_identity": identity, "package_status": "installed", "package_id": package_id("rpm", name, architecture)})
    return rows


def select_inventory():
    requested = os.environ.get("PACKAGE_MANAGER", "auto").lower()
    commands = {"dpkg": shutil.which("dpkg-query"), "rpm": shutil.which("rpm")}
    if requested in {"dpkg", "rpm"}:
        if not commands[requested]:
            raise RuntimeError(f"requested_manager_missing:{requested}")
        rows = dpkg_rows(commands[requested]) if requested == "dpkg" else rpm_rows(commands[requested])
        return requested, commands[requested], rows
    if requested != "auto":
        raise ValueError("PACKAGE_MANAGER_must_be_auto_dpkg_or_rpm")
    candidates = []
    if commands["dpkg"] and os.path.exists("/var/lib/dpkg/status"):
        rows = dpkg_rows(commands["dpkg"])
        if rows:
            candidates.append(("dpkg", commands["dpkg"], rows))
    rpm_database = any(os.path.exists(path) for path in ("/var/lib/rpm", "/usr/lib/sysimage/rpm"))
    if commands["rpm"] and rpm_database:
        rows = rpm_rows(commands["rpm"])
        if rows:
            candidates.append(("rpm", commands["rpm"], rows))
    if len(candidates) != 1:
        raise RuntimeError(f"package_manager_candidates:{len(candidates)}")
    return candidates[0]


def emit(event):
    print(json.dumps(event, ensure_ascii=True, separators=(",", ":"), sort_keys=True), flush=True)


def main():
    snapshot_epoch = int(time.time())
    snapshot_id = str(uuid.uuid4())
    manager, command, rows = select_inventory()
    if not rows:
        raise RuntimeError("empty_package_inventory")
    rows.sort(key=lambda row: (row["package_manager"], row["package_name"], row["package_arch"]))
    identities = [row["package_id"] for row in rows]
    if len(set(identities)) != len(identities):
        raise RuntimeError("duplicate_package_identity")
    version_output = run([command, "--version"]).splitlines()
    manager_tool_version = version_output[0][:240] if version_output else "unavailable"
    base = {"collector_schema": SCHEMA, "snapshot_id": snapshot_id, "snapshot_epoch": snapshot_epoch, "event_time": utc(snapshot_epoch), "package_manager": manager}
    for row in rows:
        event = dict(base)
        event.update(row)
        event["record_type"] = "package"
        emit(event)
    manifest = dict(base)
    manifest.update(record_type="manifest", collector_status="complete", package_count=len(rows), manager_tool_version=manager_tool_version)
    emit(manifest)


try:
    main()
except (OSError, UnicodeError, ValueError, RuntimeError, subprocess.SubprocessError) as error:
    epoch = int(time.time())
    emit({"collector_schema": SCHEMA, "record_type": "manifest", "collector_status": "error", "snapshot_id": str(uuid.uuid4()), "snapshot_epoch": epoch, "event_time": utc(epoch), "package_count": 0, "error_type": type(error).__name__, "error_reason": str(error)[:240]})
    raise SystemExit(1)
